    private static ThreatFocus BuildThreatFocus(
        CombatPredictionSimulator simulator,
        SimulatedCombatState combat)
    {
        IReadOnlyList<ForecastMove> moves = combat.CurrentMonsterMoves();
        uint? bestCombatId = null;
        int bestPressure = 0;
        int bestRemainingHp = int.MaxValue;
        int bestThreat = 0;
        int totalThreat = 0;
        int incomingHitCount = 0;
        IReadOnlyList<Creature> knownEnemies = combat.KnownEnemies;
        for (int enemyIndex = 0; enemyIndex < knownEnemies.Count; enemyIndex++)
        {
            Creature enemy = knownEnemies[enemyIndex];
            SimCreatureState enemyState = simulator.State.GetCreature(enemy);
            if (!combat.ContainsCreature(enemy)
                || !enemyState.IsAlive
                || enemy.CombatId is not uint combatId)
            {
                continue;
            }

            int remainingHp = Math.Max(0, enemyState.CurrentHp);
            int maxHp = Math.Max(1, enemyState.MaxHp);
            int currentThreat = 0;
            if (!combat.WillSkipNextMove(enemy))
            {
                for (int moveIndex = 0; moveIndex < moves.Count; moveIndex++)
                {
                    ForecastMove move = moves[moveIndex];
                    if (!ReferenceEquals(move.Owner, enemy))
                        continue;
                    IReadOnlyList<ForecastAttackHit> attackHits = move.AttackHits;
                    for (int hitIndex = 0; hitIndex < attackHits.Count; hitIndex++)
                    {
                        incomingHitCount++;
                        currentThreat += Math.Max(
                            0,
                            combat.AdjustMonsterMoveDamage(
                                enemy,
                                move.Move.Id,
                                attackHits[hitIndex].BaseDamage));
                    }
                }
            }
            totalThreat += currentThreat;
            int progress = Math.Max(0, maxHp - remainingHp);
            if (progress == 0)
                continue;

            int pressure = (int)Math.Min(
                int.MaxValue,
                (long)progress * (16 + Math.Min(64, currentThreat)) * 1024 / maxHp);
            if (pressure < bestPressure
                || pressure == bestPressure && currentThreat < bestThreat
                || pressure == bestPressure && currentThreat == bestThreat && remainingHp >= bestRemainingHp)
            {
                continue;
            }
            bestCombatId = combatId;
            bestPressure = pressure;
            bestRemainingHp = remainingHp;
            bestThreat = currentThreat;
        }
        return new ThreatFocus(
            bestCombatId,
            bestPressure,
            bestRemainingHp,
            bestThreat,
            totalThreat,
            incomingHitCount);
    }

    private CoverageSummary GetCoverageSummary(CombatPredictionSimulator simulator)
    {
        if (!simulator.HasRisk)
            return CoverageSummary.None;
        PredictionRiskSignature signature = simulator.History.RiskSignature;
        if (_run.CoverageCache.TryGetValue(signature, out CoverageSummary? cached))
            return cached;
        IReadOnlyList<PredictionGap> gaps = PredictionCoverage.Collect(simulator);
        CoverageSummary summary = new(gaps, gaps.Any(gap => !gap.Compensated));
        _run.CoverageCache.Add(signature, summary);
        return summary;
    }

    /// <summary>
    /// What the incoming enemy intent leaves the player at, and which one-shot death saves must be spent to
    /// get there.
    /// </summary>
    private readonly record struct ThreatProjection(int Hp, int DeathSaveHpRestored, int DeathSaveUseCount, int BlockConsumed = 0);

    private ThreatProjection ProjectHpAfterThreat(
        CombatPredictionSimulator simulator,
        SimCreatureState player)
    {
        int hp = player.CurrentHp;
        int block = player.Block;
        SimulatedCombatState simulatedCombat = (SimulatedCombatState)simulator.State.CombatState;
        // Sandpit expires after enemy turn start and forces death before the attack intent.
        // Block and one-shot death saves cannot make standing pat survive that boundary.
        foreach (PowerModel power in simulatedCombat.EffectivePowers())
        {
            if (power is SandpitPower { Amount: 1 } sandpit
                && ReferenceEquals(sandpit.Target, _player.Creature)
                && simulator.State.GetCreature(sandpit.Owner).IsAlive)
                return new ThreatProjection(0, 0, 0);
        }
        Creature? osty = simulatedCombat.GetOsty(_player);
        int ostyHp = osty == null ? 0 : simulator.State.GetCreature(osty).CurrentHp;
        ProjectedHpLossModifiers? projectedModifiers =
            simulatedCombat.GetAmount<BufferPower>(_player.Creature) > 0
            || osty != null && simulatedCombat.GetAmount<BufferPower>(osty) > 0
                ? new ProjectedHpLossModifiers() : null;
        ProjectedDeathPrevention deathPrevention = BuildProjectedDeathPrevention(
            simulator,
            simulatedCombat,
            player.MaxHp);
        bool gambitActive = simulatedCombat.GetAmount<TheGambitPower>(_player.Creature) > 0;
        IReadOnlyList<ForecastMove> moves = simulatedCombat.CurrentMonsterMoves();
        for (int moveIndex = 0; moveIndex < moves.Count; moveIndex++)
        {
            ForecastMove move = moves[moveIndex];
            if (!simulator.State.GetCreature(move.Owner).IsAlive)
                continue;
            if (simulatedCombat.WillSkipNextMove(move.Owner))
                continue;
            if (simulatedCombat.TryGetForcedMoveId(move.Owner, out string forcedMove))
            {
                if (forcedMove != "EXPLODE_MOVE"
                    || !simulatedCombat.TryGetForcedAttackDamage(move.Owner, out int forcedDamage))
                {
                    continue;
                }
                ProjectThreatHit(
                    simulator,
                    simulatedCombat,
                    move.Owner,
                    forcedDamage,
                    osty,
                    ref ostyHp,
                    ref block,
                    ref hp,
                    ref gambitActive,
                    ref deathPrevention,
                    projectedModifiers);
                continue;
            }
            IReadOnlyList<ForecastAttackHit> attackHits = move.AttackHits;
            for (int hitIndex = 0; hitIndex < attackHits.Count; hitIndex++)
            {
                int baseDamage = simulatedCombat.AdjustMonsterMoveDamage(
                    move.Owner,
                    move.Move.Id,
                    attackHits[hitIndex].BaseDamage);
                ProjectThreatHit(
                    simulator,
                    simulatedCombat,
                    move.Owner,
                    baseDamage,
                    osty,
                    ref ostyHp,
                    ref block,
                    ref hp,
                    ref gambitActive,
                    ref deathPrevention,
                    projectedModifiers);
            }
        }
        return new ThreatProjection(hp, deathPrevention.DeathSaveHpRestored, deathPrevention.UseCount,
            Math.Max(0, player.Block - block));
    }

    internal int ProjectDiagnosticHits(SimulationSnapshot snapshot, Creature attacker, params int[] hits)
        => ProjectDiagnosticThreat(snapshot, attacker, hits).Hp;

    internal (int Hp, int DeathSaveUseCount, int DeathSaveHpRestored) ProjectDiagnosticEnemyTurn(SimulationSnapshot snapshot)
    {
        ThreatProjection threat = ProjectHpAfterThreat((CombatPredictionSimulator)snapshot.Simulator,
            snapshot.Simulator.State.GetCreature(_player.Creature));
        return (threat.Hp, threat.DeathSaveUseCount, threat.DeathSaveHpRestored);
    }

    internal (int Hp, int DeathSaveUseCount, int DeathSaveHpRestored) ProjectDiagnosticThreat(
        SimulationSnapshot snapshot,
        Creature attacker,
        params int[] hits)
    {
        var simulator = (CombatPredictionSimulator)snapshot.Simulator;
        var combat = (SimulatedCombatState)simulator.State.CombatState;
        var player = simulator.State.GetCreature(_player.Creature);
        int hp = player.CurrentHp, block = player.Block;
        Creature? osty = combat.GetOsty(_player);
        int ostyHp = osty == null ? 0 : simulator.State.GetCreature(osty).CurrentHp;
        var prevention = BuildProjectedDeathPrevention(simulator, combat, player.MaxHp);
        var modifiers = new ProjectedHpLossModifiers();
        bool gambitActive = combat.GetAmount<TheGambitPower>(_player.Creature) > 0;
        foreach (int hit in hits)
            ProjectThreatHit(simulator, combat, attacker, hit, osty,
                ref ostyHp, ref block, ref hp, ref gambitActive, ref prevention, modifiers);
        return (hp, prevention.UseCount, prevention.DeathSaveHpRestored);
    }

    private void ProjectThreatHit(
        CombatPredictionSimulator simulator,
        SimulatedCombatState combat,
        Creature attacker,
        int baseDamage,
        Creature? osty,
        ref int ostyHp,
        ref int block,
        ref int playerHp,
        ref bool gambitActive,
        ref ProjectedDeathPrevention deathPrevention,
        ProjectedHpLossModifiers? projectedModifiers)
    {
        int adjustedHit = CorePowerSupport.AdjustForecastAttack(
            simulator,
            combat,
            attacker,
            _player.Creature,
            baseDamage);
        int blocked = Math.Min(block, adjustedHit);
        block -= blocked;
        decimal hpLoss = HookMirrors.ModifyHpLost(
            simulator,
            _player.Creature,
            adjustedHit - blocked,
            ValueProp.Move,
            attacker,
            null,
            HpLossHookPhase.BeforeOsty,
            out _, projectedModifiers?.Filter);
        Creature target = Hook.ModifyUnblockedDamageTarget(
            combat,
            _player.Creature,
            hpLoss,
            ValueProp.Move,
            attacker);
        if (ReferenceEquals(target, _player.Creature)
            && osty is not null
            && ostyHp > 0
            && combat.GetAmount<DieForYouPower>(osty) > 0)
        {
            target = osty;
        }
        if (ReferenceEquals(target, osty) && ostyHp <= 0)
            target = _player.Creature;
        hpLoss = HookMirrors.ModifyHpLost(
            simulator,
            target,
            hpLoss,
            ValueProp.Move,
            attacker,
            null,
            HpLossHookPhase.AfterOsty,
            out var appliedModifiers, projectedModifiers?.Filter);
        projectedModifiers?.Consume(appliedModifiers);
        int loss = Math.Max(0, (int)Math.Floor(hpLoss));
        if (ReferenceEquals(target, osty))
        {
            int absorbed = Math.Min(ostyHp, loss);
            ostyHp -= absorbed;
            // Native redirected damage applies the original target's AfterOsty hooks
            // to overkill as a separate loss. Player Buffer must also protect spillover.
            decimal overflow = HookMirrors.ModifyHpLost(
                simulator, _player.Creature, loss - absorbed, ValueProp.Move,
                attacker, null, HpLossHookPhase.AfterOsty, out var overflowModifiers,
                projectedModifiers?.Filter);
            projectedModifiers?.Consume(overflowModifiers);
            int playerLoss = Math.Max(0, (int)Math.Floor(overflow));
            playerHp -= playerLoss;
            if (playerLoss > 0 && gambitActive)
            {
                gambitActive = false;
                playerHp = 0;
            }
            deathPrevention.TryRevive(ref playerHp);
            return;
        }
        playerHp -= loss;
        if (loss > 0 && gambitActive)
        {
            gambitActive = false;
            playerHp = 0;
        }
        deathPrevention.TryRevive(ref playerHp);
    }

    // Forecasts consume finite protection locally; they never decrement live or branch Powers.
    private sealed class ProjectedHpLossModifiers
    {
        private readonly Dictionary<BufferPower, int> _remaining = [];
        public Func<AbstractModel, bool> Filter { get; }

        public ProjectedHpLossModifiers() => Filter = Includes;

        private bool Includes(AbstractModel model) => model is not BufferPower buffer
            || (_remaining.TryGetValue(buffer, out int count) ? count : buffer.Amount) > 0;

        public void Consume(IEnumerable<AbstractModel> modifiers)
        {
            foreach (AbstractModel model in modifiers)
                if (model is BufferPower buffer)
                    _remaining[buffer] = (_remaining.TryGetValue(buffer, out int count) ? count : buffer.Amount) - 1;
        }
    }

    private ProjectedDeathPrevention BuildProjectedDeathPrevention(
        CombatPredictionSimulator simulator,
        SimulatedCombatState combat,
        int playerMaxHp)
    {
        int fairyCount = 0;
        for (int slot = 0; slot < root.PotionSlotCount; slot++)
        {
            if (combat.GetPotionAtSlot(_player, slot) is FairyInABottle)
                fairyCount++;
        }

        LizardTail? lizardTail = null;
        IReadOnlyList<RelicModel> relics = combat.RelicsOf(_player);
        for (int index = 0; index < relics.Count; index++)
        {
            if (relics[index] is LizardTail candidate
                && !LizardTailMirrors.WasUsed(candidate, simulator))
            {
                lizardTail = candidate;
                break;
            }
        }
        return new ProjectedDeathPrevention(
            fairyCount,
            (int)FairyInABottleMirrors.HealAmount(playerMaxHp),
            lizardTail != null,
            lizardTail == null ? 0 : (int)LizardTailMirrors.HealAmount(lizardTail, playerMaxHp));
    }

    private struct ProjectedDeathPrevention(
        int fairyCount,
        int fairyHeal,
        bool lizardTailAvailable,
        int lizardTailHeal)
    {
        public int DeathSaveHpRestored { get; private set; }
        public int UseCount { get; private set; }

        public void TryRevive(ref int hp)
        {
            if (hp > 0)
                return;
            if (fairyCount > 0)
            {
                fairyCount--;
                hp = fairyHeal;
                DeathSaveHpRestored += fairyHeal;
                UseCount++;
                return;
            }
            if (!lizardTailAvailable)
                return;
            lizardTailAvailable = false;
            // Projected HP can run below zero; the real revive heals from zero, so the restored amount is
            // the full heal either way.
            DeathSaveHpRestored += lizardTailHeal;
            UseCount++;
            hp = lizardTailHeal;
        }
    }

    private StateFingerprint BuildStateKey(
        int turn,
        SimCreatureState player,
        SimPlayerCombatState playerState,
        SimulatedCombatState simulatedCombat,
        CombatPredictionSimulator simulator,
        int shufflesCrossed,
        IReadOnlySet<uint> processedEnemyDeaths)
    {
        StateFingerprintBuilder key = new();
        key.Add(turn);
        key.Add(player.CurrentHp);
        key.Add(player.MaxHp);
        key.Add(player.Block);
        key.Add(playerState.Energy);
        key.Add((int)playerState.Phase);
        key.Add(playerState.Stars);
        key.Add(shufflesCrossed);
        Player owner = _player;
        if (simulatedCombat.GetOsty(owner) is { } osty)
        {
            key.Add(simulator.State.GetCreature(osty).CurrentHp);
            key.Add(simulatedCombat.GetOstyMaxHp(simulator, owner));
            key.Add(simulatedCombat.IsOstyHittable(simulator, owner));
        }
        else
        {
            key.Add(0);
            key.Add(0);
            key.Add(false);
        }
        IReadOnlyList<Creature> knownEnemies = simulatedCombat.KnownEnemies;
        for (int enemyIndex = 0; enemyIndex < knownEnemies.Count; enemyIndex++)
        {
            Creature enemy = knownEnemies[enemyIndex];
            SimCreatureState enemyState = simulator.State.GetCreature(enemy);
            key.Add(enemy.Monster?.Id.Entry);
            key.Add(enemy.CombatId ?? uint.MaxValue);
            key.Add(simulatedCombat.ContainsCreature(enemy));
            key.Add(enemyState.CurrentHp);
            key.Add(enemyState.MaxHp);
            key.Add(enemyState.Block);
        }
        SearchMeasurement pileFingerprintMeasurement = _run.Performance.Begin();
        AppendPile(ref key, playerState.Hand, 'H');
        AppendPile(ref key, playerState.DrawPile, 'D');
        AppendPile(ref key, playerState.DiscardPile, 'C');
        AppendPile(ref key, playerState.ExhaustPile, 'X');
        AppendOrbs(ref key, simulator, playerState.OrbQueue);
        _run.Performance.End(SearchMetricPhase.PileFingerprint, pileFingerprintMeasurement);
        AppendRngState(ref key, simulator.Rng.ShuffleState);
        AppendRngState(ref key, simulator.Rng.CombatCardGenerationState);
        AppendRngState(ref key, simulator.Rng.CombatPotionGenerationState);
        AppendRngState(ref key, simulator.Rng.CombatCardSelectionState);
        AppendRngState(ref key, simulator.Rng.CombatEnergyCostsState);
        AppendRngState(ref key, simulator.Rng.CombatTargetsState);
        AppendRngState(ref key, simulator.Rng.CombatOrbGenerationState);
        AppendRngState(ref key, simulator.Rng.MonsterAiState);
        AppendRngState(ref key, simulator.Rng.NicheState);
        ulong deathsFirst = 0;
        ulong deathsSecond = 0;
        foreach (uint combatId in processedEnemyDeaths)
        {
            deathsFirst += StateFingerprintBuilder.MixFirst(combatId);
            deathsSecond += StateFingerprintBuilder.MixSecond(combatId);
        }
        key.Add(processedEnemyDeaths.Count);
        key.Add(deathsFirst);
        key.Add(deathsSecond);
        if (_historyDependencies != CombatHistoryDependencies.None)
            CombatHistoryCounterKey.Append(ref key, simulator, _player, _historyDependencies);
        SearchMeasurement combatFingerprintMeasurement = _run.Performance.Begin();
        simulatedCombat.AppendFingerprint(ref key, simulator);
        _run.Performance.End(SearchMetricPhase.CombatFingerprint, combatFingerprintMeasurement);
        return ApplyStateKeySalt(key.Finish());
    }

    /// <summary>
    /// 状态键是若干个排序与分组的下游键（同一指纹值既当相等判据又当决胜序）。异或常量是双射，
    /// 所以只动数值、不动相等关系，可以把「键的编码方式影响决策」单独量出来。
    /// </summary>
    private StateFingerprint ApplyStateKeySalt(StateFingerprint fingerprint)
    {
        int salt = policy.StateKeySalt;
        if (salt == 0)
            return fingerprint;
        return new StateFingerprint(
            fingerprint.First ^ unchecked((ulong)salt * 0x9E3779B97F4A7C15UL + 0xD1B54A32D192ED03UL),
            fingerprint.Second ^ unchecked((ulong)salt * 0xC2B2AE3D27D4EB4FUL + 0x165667B19E3779F9UL));
    }

    private static void AppendRngState(ref StateFingerprintBuilder key, Rng rng)
    {
        AppendRngState(ref key, rng.CaptureState());
    }

    private static void AppendRngState(ref StateFingerprintBuilder key, PredictionRngState state)
    {
        key.Add(state.Counter);
        key.Add(state.State0);
        key.Add(state.State1);
        key.Add(state.State2);
        key.Add(state.State3);
    }

    internal static StateFingerprint CaptureRngStateFingerprintForTesting(Rng rng)
    {
        StateFingerprintBuilder key = new();
        AppendRngState(ref key, rng);
        return key.Finish();
    }

    private static void AppendOrbs(
        ref StateFingerprintBuilder key,
        CombatPredictionSimulator simulator,
        SimOrbQueue queue)
    {
        key.Add('O');
        key.Add(queue.Capacity);
        key.Add(queue.Orbs.Count);
        foreach (OrbModel orb in queue.Orbs)
        {
            key.Add(orb.Id.Entry);
            key.Add(Engine.InCombat.Mirrors.Orbs.OrbMirrors.GetPassiveValue(simulator, orb));
            key.Add(Engine.InCombat.Mirrors.Orbs.OrbMirrors.GetEvokeValue(simulator, orb));
        }
    }

    private StateFingerprint BuildPlayableCardKey(PredictedCard card)
        => BuildCardStateFingerprint(card);

    private StateFingerprint BuildCardStateFingerprint(PredictedCard card)
    {
        if (card.TryGetCachedFingerprint(out ulong cachedFirst, out ulong cachedSecond))
            return new StateFingerprint(cachedFirst, cachedSecond);
        SearchMeasurement measurement = _run.Performance.Begin();
        StateFingerprint fingerprint = CaptureCardStateFingerprintForTesting(card);
        card.SetCachedFingerprint(fingerprint.First, fingerprint.Second);
        _run.Performance.End(SearchMetricPhase.CardFingerprintMiss, measurement);
        return fingerprint;
    }

    internal static StateFingerprint CaptureCardStateFingerprintForTesting(PredictedCard card)
    {
        CardModel preview = card.Preview;
        StateFingerprintBuilder key = new();
        key.Add(preview.Id.Entry);
        key.Add(preview.CurrentUpgradeLevel);
        key.Add(preview.EnergyCost.CostsX);
        key.Add(preview.EnergyCost.GetWithModifiers(CostModifiers.Local));
        key.Add(preview.HasStarCostX);
        key.Add(preview.CurrentStarCost);
        CardCostStateSupport.Append(ref key, preview);
        key.Add(preview.BaseReplayCount);
        key.Add(preview.ExhaustOnNextPlay);
        key.Add(preview.IsSlyThisTurn);
        key.Add(preview.ShouldRetainThisTurn);
        AppendLocalCardKeywords(ref key, preview);
        key.Add(preview.DeckVersion != null);
        key.Add(preview.HasBeenRemovedFromState);
        EnchantmentStateSupport.Append(ref key, preview.Enchantment);
        key.Add(preview.Affliction?.Id.Entry);
        key.Add(preview.Affliction?.Amount ?? 0);
        AppendDynamicVars(ref key, preview, preview.DynamicVars);
        switch (preview)
        {
            case Claw claw:
                key.Add(claw.ExtraDamageFromClawPlays);
                break;
            case GeneticAlgorithm geneticAlgorithm:
                key.Add(geneticAlgorithm.IncreasedBlock);
                break;
            case Maul maul:
                key.Add(maul._extraDamageFromMaulPlays);
                break;
            case MadScience madScience:
                key.Add((int)madScience.TinkerTimeType);
                key.Add((int)madScience.TinkerTimeRider);
                break;
            case Rampage rampage:
                key.Add(rampage.ExtraDamageFromPlays);
                break;
            case TheScythe scythe:
                key.Add(scythe.IncreasedDamage);
                break;
        }
        if (card.HasExternallyMutableAttachedModels)
            AppendBaseLibCardModifiers(ref key, preview);
        return key.Finish();
    }

    private static void AppendLocalCardKeywords(
        ref StateFingerprintBuilder key,
        CardModel card)
    {
        ulong commonKeywordMask = 0;
        SortedSet<int>? overflowKeywords = null;
        foreach (CardKeyword keyword in card.GetKeywordsWithSources(KeywordSources.Local))
        {
            int value = (int)keyword;
            if ((uint)value < 64)
            {
                commonKeywordMask |= 1UL << value;
                continue;
            }
            (overflowKeywords ??= []).Add(value);
        }
        key.Add(commonKeywordMask);
        key.Add(overflowKeywords?.Count ?? 0);
        if (overflowKeywords == null)
            return;
        foreach (int keyword in overflowKeywords)
            key.Add(keyword);
    }

    private static void AppendBaseLibCardModifiers(
        ref StateFingerprintBuilder key,
        CardModel card)
    {
        CardAttachedModelCollection modifiers =
            PredictionModModelSupport.GetCardAttachedListeners(card);
        key.Add('M');
        key.Add(modifiers.Count);
        for (int index = 0; index < modifiers.Count; index++)
        {
            AbstractModel modifier = modifiers[index];
            Type type = modifier.GetType();
            key.Add(type.Assembly.GetName().Name);
            key.Add(type.FullName);
            BaseLibCardModifierFingerprintState state =
                PredictionModModelSupport.CaptureBaseLibCardModifierFingerprintState(modifier);
            key.Add(state.Amount);
            key.Add(state.Priority);
            key.Add(state.IntProperties.Length);
            foreach ((string name, int value) in state.IntProperties)
            {
                key.Add(name);
                key.Add(value);
            }
            key.Add(state.AdditionalProperties.Length);
            foreach ((string name, string value) in state.AdditionalProperties)
            {
                key.Add(name);
                key.Add(value);
            }
        }
    }

    private void AppendPile(ref StateFingerprintBuilder key, SimCardPile pile, char marker)
    {
        if ((policy.PileOrderInvariantMask & PileOrderInvariantBit(marker)) != 0)
        {
            AppendUnorderedPileKey(ref key, pile, marker);
            return;
        }
        key.Add(marker);
        key.Add(pile.Cards.Count);
        if (pile.TryGetCachedFingerprint(out ulong cachedFirst, out ulong cachedSecond))
        {
            key.Add(cachedFirst);
            key.Add(cachedSecond);
            return;
        }
        SearchMeasurement measurement = _run.Performance.Begin();
        StateFingerprintBuilder pileKey = new();
        pileKey.Add(pile.Cards.Count);
        foreach (PredictedCard card in pile)
        {
            StateFingerprint cardFingerprint = BuildCardStateFingerprint(card);
            pileKey.Add(cardFingerprint.First);
            pileKey.Add(cardFingerprint.Second);
        }
        StateFingerprint fingerprint = pileKey.Finish();
        pile.SetCachedFingerprint(fingerprint.First, fingerprint.Second);
        _run.Performance.End(SearchMetricPhase.PileFingerprintMiss, measurement);
        key.Add(fingerprint.First);
        key.Add(fingerprint.Second);
    }

    private static void AppendDynamicVars(
        ref StateFingerprintBuilder key,
        AbstractModel model,
        IReadOnlyDictionary<string, MegaCrit.Sts2.Core.Localization.DynamicVars.DynamicVar> dynamicVars)
    {
        ulong first = 0;
        ulong second = 0;
        int count = 0;
        foreach ((string name, MegaCrit.Sts2.Core.Localization.DynamicVars.DynamicVar value) in dynamicVars)
        {
            if (!SemanticStateFieldPolicy.IsSemantic(model, name, value))
                continue;
            StateFingerprintBuilder item = new();
            item.Add(name);
            item.Add(value.BaseValue);
            if (value is MegaCrit.Sts2.Core.Localization.DynamicVars.StringVar stringVar)
                item.Add(stringVar.StringValue);
            StateFingerprint fingerprint = item.Finish();
            first += StateFingerprintBuilder.MixFirst(fingerprint.First);
            second += StateFingerprintBuilder.MixSecond(fingerprint.Second);
            count++;
        }
        key.Add(count);
        key.Add(first);
        key.Add(second);
    }

}

using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using System.Runtime.CompilerServices;

namespace CombatSolver.Engine.Common;

internal sealed class PredictedCard : IComparable<PredictedCard>
{
    // A COW preview keeps the combat card's identity across hook snapshots. Gameplay
    // clones acquire their own identity when they enter a new prediction wrapper.
    private static readonly ConditionalWeakTable<CardModel, object> CardIdentities = new();

    private sealed class PreviewStorage(CardModel original, CardModel? preview)
    {
        public CardModel Original { get; } = original;
        public CardModel? Preview { get; } = preview;
        public object Identity { get; } = RegisterIdentity(original, preview);
        public volatile bool Shared;

        private static object RegisterIdentity(CardModel original, CardModel? preview)
        {
            object identity = CardIdentities.GetValue(original, static _ => new object());
            if (preview != null && !ReferenceEquals(CardIdentities.GetValue(preview, _ => identity), identity))
                throw new InvalidOperationException("A card preview belongs to a different combat-card identity.");
            return identity;
        }

        private bool _hasCachedFingerprint;
        private ulong _cachedFingerprintFirst;
        private ulong _cachedFingerprintSecond;
        private string? _cachedChoiceKey;

        public bool TryGetCachedFingerprint(out ulong first, out ulong second)
        {
            if (!Volatile.Read(ref _hasCachedFingerprint))
            {
                first = 0;
                second = 0;
                return false;
            }
            first = _cachedFingerprintFirst;
            second = _cachedFingerprintSecond;
            return true;
        }

        public void SetCachedFingerprint(ulong first, ulong second)
        {
            _cachedFingerprintFirst = first;
            _cachedFingerprintSecond = second;
            Volatile.Write(ref _hasCachedFingerprint, true);
        }

        public bool TryGetCachedChoiceKey(out string key)
        {
            string? cached = Volatile.Read(ref _cachedChoiceKey);
            key = cached ?? string.Empty;
            return cached is not null;
        }

        public void SetCachedChoiceKey(string key)
            => Volatile.Write(ref _cachedChoiceKey, key);

        public void InvalidateCaches()
        {
            Volatile.Write(ref _hasCachedFingerprint, false);
            Volatile.Write(ref _cachedChoiceKey, null);
        }
    }

    private PreviewStorage _previewStorage;
    private SimCardPile? _ownerPile;
    private Action? _mutationObserver;
    private bool _observeEveryPreviewMutation;
    private bool _isolateAttachedModelsOnFork;

    // Entry inspection belongs to this wrapper, including root cards that need no
    // entry effect. Fork preserves it; Clone starts unchecked. Root membership is
    // frozen for the search, so a checked card never needs another root-set lookup.
    internal bool HasCheckedPowerAfflictionEntry { get; private set; }

    internal bool TryMarkPowerAfflictionEntryChecked()
    {
        if (HasCheckedPowerAfflictionEntry)
            return false;
        HasCheckedPowerAfflictionEntry = true;
        return true;
    }

    public PredictedCard(CardModel original, CardModel? preview = null)
    {
        _previewStorage = new PreviewStorage(original, preview);
    }

    private PredictedCard(PreviewStorage previewStorage)
        => _previewStorage = previewStorage;

    public CardModel Original => _previewStorage.Original;

    public CardModel Preview => _previewStorage.Preview ?? _previewStorage.Original;

    internal SimCardPile? OwnerPile => _ownerPile;

    internal bool HasExternallyMutableAttachedModels => _isolateAttachedModelsOnFork;

    public CardModel MutablePreview
    {
        get
        {
            _ownerPile?.InvalidateCardFingerprint(this);
            if (_observeEveryPreviewMutation)
                NotifyHookListenerStructureChanged();
            CardModel? preview = _previewStorage.Preview;
            if (preview is null)
            {
                preview = PredictionUtils.CloneCardStateForSimulation(_previewStorage.Original);
                _previewStorage = new PreviewStorage(_previewStorage.Original, preview);
                if (!_observeEveryPreviewMutation)
                    NotifyHookListenerStructureChanged();
            }
            else if (_previewStorage.Shared)
            {
                preview = PredictionUtils.CloneCardStateForSimulation(preview);
                _previewStorage = new PreviewStorage(_previewStorage.Original, preview);
                if (!_observeEveryPreviewMutation)
                    NotifyHookListenerStructureChanged();
            }
            else
            {
                _previewStorage.InvalidateCaches();
            }
            return preview;
        }
    }

    internal void MaterializePreview()
    {
        if (_previewStorage.Preview is not null)
            return;
        _previewStorage = new PreviewStorage(
            _previewStorage.Original,
            PredictionUtils.CloneCardStateForSimulation(_previewStorage.Original));
    }

    public static List<PredictedCard> FromCards(IEnumerable<CardModel> cards)
    {
        return cards.Select(card => new PredictedCard(card)).ToList();
    }

    public static PredictedCard FromGenerated(CardModel card)
    {
        return new(card, card);
    }

    public static PredictedCard Create(CardModel canonicalCard, Player player)
    {
        return FromGenerated(PredictionUtils.CreateCard(canonicalCard, player));
    }

    public bool References(object? card)
    {
        return ReferenceEquals(_previewStorage.Original, card)
            || ReferenceEquals(_previewStorage.Preview, card)
            || card is CardModel model && CardIdentities.TryGetValue(model, out object? identity)
                && ReferenceEquals(_previewStorage.Identity, identity);
    }

    // Clones the prediction wrapper state only. Combat effects that generate a gameplay
    // clone of a card should use CombatPredictedCardExtensions.CreateClone instead.
    public PredictedCard Clone()
    {
        return new PredictedCard(_previewStorage.Original, _previewStorage.Preview is { } preview
            ? PredictionUtils.CloneCardStateForSimulation(preview)
            : null)
        {
            _isolateAttachedModelsOnFork = _isolateAttachedModelsOnFork,
        };
    }

    internal PredictedCard Fork(PredictionForkContext context)
    {
        PreviewStorage forkStorage;
        if (_isolateAttachedModelsOnFork)
        {
            CardModel source = _previewStorage.Preview ?? _previewStorage.Original;
            forkStorage = new PreviewStorage(
                _previewStorage.Original,
                PredictionUtils.CloneCardStateForSimulation(source));
        }
        else
        {
            _previewStorage.Shared = true;
            forkStorage = _previewStorage;
        }
        PredictedCard fork = new(forkStorage)
        {
            _isolateAttachedModelsOnFork = _isolateAttachedModelsOnFork,
            HasCheckedPowerAfflictionEntry = HasCheckedPowerAfflictionEntry,
        };
        context.Register(this, fork);
        return fork;
    }

    internal bool TryGetCachedFingerprint(out ulong first, out ulong second)
    {
        if (_isolateAttachedModelsOnFork)
        {
            first = 0;
            second = 0;
            return false;
        }
        return _previewStorage.TryGetCachedFingerprint(out first, out second);
    }

    internal void SetCachedFingerprint(ulong first, ulong second)
    {
        if (_isolateAttachedModelsOnFork)
            return;
        _previewStorage.SetCachedFingerprint(first, second);
    }

    internal bool TryGetCachedChoiceKey(out string key)
    {
        if (_isolateAttachedModelsOnFork)
        {
            key = string.Empty;
            return false;
        }
        return _previewStorage.TryGetCachedChoiceKey(out key);
    }

    internal void SetCachedChoiceKey(string key)
    {
        if (!_isolateAttachedModelsOnFork)
            _previewStorage.SetCachedChoiceKey(key);
    }

    internal void InvalidateCaches()
    {
        _ownerPile?.InvalidateCardFingerprint(this);
        _previewStorage.InvalidateCaches();
    }

    internal void SetOwnerPile(SimCardPile? pile, SimCardPile? membershipChangedPile = null)
    {
        if (!ReferenceEquals(_ownerPile, pile))
        {
            if (_ownerPile is not null && ReferenceEquals(_ownerPile, membershipChangedPile))
                _ownerPile.InvalidateMembershipStateFingerprints();
            else
                _ownerPile?.InvalidateFingerprint();
        }
        _ownerPile = pile;
        if (_isolateAttachedModelsOnFork)
            pile?.DisableFingerprintCache();
        if (ReferenceEquals(pile, membershipChangedPile))
            _mutationObserver?.Invoke();
        else
            NotifyHookListenerStructureChanged();
    }

    internal void SetMutationObserver(Action? observer, bool observeEveryPreviewMutation = false)
    {
        _mutationObserver = observer;
        _observeEveryPreviewMutation = observer is not null && observeEveryPreviewMutation;
    }

    internal void EnableAttachedModelForkIsolation()
    {
        _isolateAttachedModelsOnFork = true;
        _previewStorage.InvalidateCaches();
        _ownerPile?.DisableFingerprintCache();
        PredictionModModelSupport.RegisterBaseLibCardModifierOwner(Preview);
    }

    // The hook-listener cache contains the preview card object plus its optional attached
    // affliction/enchantment. Ordinary vanilla card-field mutations keep those identities stable
    // and do not require rebuilding a deck-sized listener list. A BaseLib CardModifier can change
    // its opaque DirectModifiers membership during any mutable access, so callers opt back into the
    // conservative per-access invalidation policy while such modifiers are present.
    internal void NotifyHookListenerStructureChanged()
    {
        // A nested query can refill an empty projection before attachment writes
        // finish. Mark this card again so the completed structure is rechecked.
        _ownerPile?.InvalidateHookCardProjection(this);
        _mutationObserver?.Invoke();
    }

    public int CompareTo(PredictedCard? other)
    {
        return Preview.CompareTo(other?.Preview);
    }
}

using System.Collections.Concurrent;
using System.Diagnostics;
using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver.Engine.Common;
namespace CombatSolver;
internal static class TaskContextReadCensus
{
    private sealed class Epoch(long id) { public readonly long Id = id; public long Version; }
    private static long _nextId;
    private static readonly ConditionalWeakTable<object, Epoch> Epochs = new();
    private static readonly ConditionalWeakTable<object, Shard> Workers = new();
    private static readonly ConcurrentBag<Shard> Shards = new();
    private static readonly FieldInfo Storage = typeof(PredictedCard).GetField("_previewStorage", BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static readonly FieldInfo Opaque = typeof(PredictedCard).GetField("_isolateAttachedModelsOnFork", BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static readonly Type StorageType = Storage.FieldType;
    private static readonly FieldInfo Preview = StorageType.GetField("<Preview>k__BackingField", BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static readonly FieldInfo Shared = StorageType.GetField("Shared")!;
    private static readonly FieldInfo HasFingerprint = StorageType.GetField("_hasCachedFingerprint", BindingFlags.Instance | BindingFlags.NonPublic)!;
    private static readonly FieldInfo Mirror = typeof(SimulatedCombatState).GetField("_mirroredHookListeners", BindingFlags.Instance | BindingFlags.NonPublic)!;
    static TaskContextReadCensus()
    {
        string output = Environment.GetEnvironmentVariable("COMBATSOLVER_TASK_CONTEXT_READ_CENSUS_OUT") ?? throw new InvalidOperationException("Missing census output");
        AppDomain.CurrentDomain.ProcessExit += (_, _) => File.WriteAllText(output, JsonSerializer.Serialize(new {
            diagnosticOnly = true, originalBuildAlwaysExecuted = true,
            scope = "Exact COW storage identity plus a diagnostic invalidation epoch; no context reuse. Shared-only and versioned hypotheses reported separately. Native/global read purity remains unproven.",
            stopwatchFrequency = Stopwatch.Frequency, storageIdentities = _nextId, workers = Shards.Select(s => s.Export()).ToArray()
        }, new JsonSerializerOptions { WriteIndented = true }));
    }
    private static Epoch ForStorage(object storage) => Epochs.GetValue(storage, static _ => new Epoch(Interlocked.Increment(ref _nextId)));
    internal static void Invalidate(object storage) { Interlocked.Increment(ref ForStorage(storage).Version); }
    private readonly record struct Identity(long Id, long Epoch);
    private readonly record struct Key(StateFingerprint Deck, int Cards, int EnemyHp, int Damage, int Hits, StrategicEffectRequirements Requirements, bool SkillsExhaust);
    private sealed record Entry(Key Key, Identity[] Ids, StrategicEffectContext Value, bool Shared, bool CallbacksEmpty);
    public static void Observe(object worker, SimulatedCombatState combat, StateFingerprint deck,
        IReadOnlyList<PredictedCard> cards, int hp, int damage, int hits,
        StrategicEffectRequirements requirements, bool skillsExhaust, StrategicEffectContext value, long ticks)
    {
        var shard = Workers.GetValue(worker, static _ => { Shard s = new(); Shards.Add(s); return s; });
        shard.Calls++; shard.Cards += cards.Count; shard.Ticks += ticks;
        if (requirements == StrategicEffectRequirements.None) { shard.None++; return; }
        var ids = new Identity[cards.Count]; bool shared = true; string? reason = null;
        for (int i=0;i<cards.Count;i++)
        {
            var card = cards[i]; var storage = Storage.GetValue(card)!;
            if ((bool)Opaque.GetValue(card)!) { reason = "Opaque"; break; }
            if (Preview.GetValue(storage) is null) { reason = "Unmaterialized"; break; }
            if (!(bool)HasFingerprint.GetValue(storage)!) { reason = "NoFingerprint"; break; }
            shared &= (bool)Shared.GetValue(storage)!;
            var epoch = ForStorage(storage); ids[i] = new(epoch.Id, Volatile.Read(ref epoch.Version));
        }
        if (reason != null) { shard.Rejections[reason] = shard.Rejections.GetValueOrDefault(reason)+1; return; }
        shard.Eligible++; shard.EligibleCards += cards.Count;
        if (shared) shard.AllShared++;
        MirroredHookMask mask = 0;
        if ((requirements & (StrategicEffectRequirements.SkillEnergySpend | StrategicEffectRequirements.PowerEnergySpend)) != 0)
            mask |= MirroredHookMask.TryModifyEnergyCostInCombat | MirroredHookMask.TryModifyEnergyCostInCombatLate;
        if ((requirements & (StrategicEffectRequirements.ExhaustPlays | StrategicEffectRequirements.ShivPlays | StrategicEffectRequirements.AttackHits)) != 0)
            mask |= MirroredHookMask.TryModifyKeywordsInCombat;
        bool empty = mask == 0 || Mirror.GetValue(combat) is MirroredHookListenerSnapshot snapshot && !snapshot.HasAny(mask);
        if (empty) shard.CallbackEmpty++;
        Key key = new(deck,cards.Count,hp,damage,hits,requirements,skillsExhaust);
        foreach (var lru in shard.Caches) lru.Observe(new(key,ids,value,shared,empty),ticks);
        foreach(var id in ids)
            foreach(var lru in shard.CardCaches)
                lru.Observe(new(id.Id,id.Epoch,requirements,skillsExhaust),empty);
    }
    private readonly record struct CardKey(long Id,long Epoch,StrategicEffectRequirements Requirements,bool SkillsExhaust);
    private sealed class CardLru(int capacity)
    {
        private readonly Dictionary<CardKey,LinkedListNode<(CardKey Key,bool Empty)>> _index=[];
        private readonly LinkedList<(CardKey Key,bool Empty)> _lru=new();
        private long _calls,_hits,_eligibleCalls,_eligibleHits;
        public void Observe(CardKey key,bool empty)
        {
            _calls++;if(!empty)return;_eligibleCalls++;
            if(_index.TryGetValue(key,out var node))
            {
                _hits++;if(empty&&node.Value.Empty)_eligibleHits++;
                node.Value=(key,empty);_lru.Remove(node);_lru.AddFirst(node);return;
            }
            var added=_lru.AddFirst((key,empty));_index.Add(key,added);
            if(_index.Count>capacity){var last=_lru.Last!;_index.Remove(last.Value.Key);_lru.RemoveLast();}
        }
        public object Export()=>new {capacity,calls=_calls,hits=_hits,eligibleCalls=_eligibleCalls,eligibleHits=_eligibleHits,retained=_index.Count};
    }
    private sealed class Shard
    {
        public long Calls,Cards,Ticks,None,Eligible,EligibleCards,AllShared,CallbackEmpty;
        public readonly Dictionary<string,long> Rejections = [];
        public readonly Lru[] Caches = [new(16),new(128)];
        public readonly CardLru[] CardCaches = [new(512),new(1024)];
        public object Export() => new { Calls,Cards,Ticks,None,Eligible,EligibleCards,AllShared,CallbackEmpty,Rejections,caches=Caches.Select(c=>c.Export()).ToArray(),cardCaches=CardCaches.Select(c=>c.Export()).ToArray() };
    }
    private sealed class Lru(int capacity)
    {
        private readonly Dictionary<Key,LinkedListNode<Entry>> _index = [];
        private readonly LinkedList<Entry> _lru = new();
        private long _calls,_semanticHits,_exactHits,_exactCards,_bothEmptyHits,_bothEmptyCards,_sharedHits,_sharedCards,_mismatches,_ticks;
        private long _multisetHits,_multisetCards,_multisetEmptyHits,_multisetEmptyCards,_multisetMismatches;
        private readonly Dictionary<int,long> _changedCardCounts = [];
        public void Observe(Entry current,long ticks)
        {
            _calls++;
            if (_index.TryGetValue(current.Key,out var node))
            {
                _semanticHits++;
                bool exact = node.Value.Ids.AsSpan().SequenceEqual(current.Ids);
                Identity[] before = node.Value.Ids.OrderBy(x=>x.Id).ThenBy(x=>x.Epoch).ToArray();
                Identity[] after = current.Ids.OrderBy(x=>x.Id).ThenBy(x=>x.Epoch).ToArray();
                bool sameMultiset = before.AsSpan().SequenceEqual(after);
                int a=0,b=0,changed=0;
                while(a<before.Length && b<after.Length)
                {
                    int c=before[a].Id.CompareTo(after[b].Id);
                    if(c==0)c=before[a].Epoch.CompareTo(after[b].Epoch);
                    if(c==0){a++;b++;}else if(c<0){a++;changed++;}else b++;
                }
                changed += before.Length-a;
                _changedCardCounts[changed]=_changedCardCounts.GetValueOrDefault(changed)+1;
                if(sameMultiset)
                {
                    _multisetHits++;_multisetCards+=current.Key.Cards;
                    if(node.Value.CallbacksEmpty && current.CallbacksEmpty){_multisetEmptyHits++;_multisetEmptyCards+=current.Key.Cards;}
                    if(!node.Value.Value.Equals(current.Value))_multisetMismatches++;
                }
                if (exact)
                {
                    _exactHits++;_exactCards+=current.Key.Cards;_ticks+=ticks;
                    if (node.Value.CallbacksEmpty && current.CallbacksEmpty) { _bothEmptyHits++;_bothEmptyCards+=current.Key.Cards; }
                    if (node.Value.Shared && current.Shared) { _sharedHits++;_sharedCards+=current.Key.Cards; }
                    if (!node.Value.Value.Equals(current.Value)) _mismatches++;
                }
                node.Value=current;_lru.Remove(node);_lru.AddFirst(node);return;
            }
            var added=_lru.AddFirst(current);_index.Add(current.Key,added);
            if (_index.Count>capacity) { var last=_lru.Last!;_index.Remove(last.Value.Key);_lru.RemoveLast(); }
        }
        public object Export()=>new {capacity,calls=_calls,semanticHits=_semanticHits,exactHits=_exactHits,exactCards=_exactCards,bothEmptyHits=_bothEmptyHits,bothEmptyCards=_bothEmptyCards,sharedHits=_sharedHits,sharedCards=_sharedCards,mismatches=_mismatches,originalExactHitTicks=_ticks,retained=_index.Count,multisetHits=_multisetHits,multisetCards=_multisetCards,multisetEmptyHits=_multisetEmptyHits,multisetEmptyCards=_multisetEmptyCards,multisetMismatches=_multisetMismatches,changedCardCounts=_changedCardCounts};
    }
}

